// Port UI build — zero dependencies. `node scripts/build.mjs`
// Reads src/ (tokens, presets, css, js, icons) and writes dist/.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const src = (p) => path.join(root, "src", p);
const out = (p) => path.join(root, "dist", p);
const read = (p) => fs.readFileSync(p, "utf8");
const write = (p, s) => { fs.mkdirSync(path.dirname(p), { recursive: true }); fs.writeFileSync(p, s); };
const pkg = JSON.parse(read(path.join(root, "package.json")));
const banner = `/*! @port/ui v${pkg.version} — Port design system. Generated by scripts/build.mjs; edit src/, not dist/. */\n`;

fs.rmSync(path.join(root, "dist"), { recursive: true, force: true });

/* ---------- tokens ---------- */
const T = JSON.parse(read(src("tokens/tokens.json")));
const PRE = JSON.parse(read(src("tokens/presets.json")));
const themes = T.color.themes.map((t) => t.id); // ["light","dark"]
const val = (v, th) => {
  const x = typeof v === "string" ? v : (v[th] ?? v[themes[0]]);
  return x.replace(/^\{([\w.-]+)\}$/, "var(--$1)");
};
const decls = (obj) => Object.entries(obj).map(([k, v]) => `  --${k}: ${v};`).join("\n");
const colorVars = (th) => Object.fromEntries([
  ...T.color.tokens.map((t) => [t.name, val(t.value, th)]),
  ...(T.shadow?.tokens || []).map((t) => [t.name, val(t.value, th)]),
]);
const staticVars = Object.fromEntries([
  ...T.spacing.tokens.map((t) => [t.name, t.value]),
  ...T.radius.tokens.map((t) => [t.name, t.value]),
  ...(T.motion?.tokens || []).map((t) => ["motion-" + t.name, t.value]),
  ...Object.entries(T.type.families).map(([k, v]) => ["font-" + k, v]),
]);
let tokensCss = banner +
`/* Tokens are scoped to .port so Port can live inside any app without touching its globals.
   Theme: data-theme="light|dark" on the .port root (Port.init sets it, following the OS when theme is "system").
   Without JS, the OS preference still applies through the media query below. */
.port, .port[data-theme="light"] {
${decls(colorVars("light"))}
  color-scheme: light;
}
.port[data-theme="dark"] {
${decls(colorVars("dark"))}
  color-scheme: dark;
}
@media (prefers-color-scheme: dark) {
  .port:not([data-theme]) {
${decls(colorVars("dark")).replace(/^/gm, "  ")}
    color-scheme: dark;
  }
}
.port {
${decls(staticVars)}
}
`;
// type style utility classes
for (const g of T.type.groups) for (const s of g.styles) {
  const fam = s.family || g.family;
  tokensCss += `.port .t-${s.name} { font-family: var(--font-${fam}); font-size: ${s.fontSize}; line-height: ${s.lineHeight}; font-weight: ${s.fontWeight}${s.letterSpacing ? `; letter-spacing: ${s.letterSpacing}` : ""}${fam === "mono" ? "; font-variant-numeric: tabular-nums" : ""}${s.name === "eyebrow" ? "; text-transform: uppercase" : ""}; }\n`;
}
write(out("tokens.css"), tokensCss);

/* ---------- theme presets ---------- */
const presetCss = {};
for (const p of PRE.presets) {
  if (!Object.keys(p.light).length && !Object.keys(p.dark).length) continue;
  let css = banner + `/* Preset: ${p.name} — ${p.description} */\n`;
  css += `.port[data-palette="${p.id}"]:not([data-theme="dark"]) {\n${decls(p.light)}\n}\n`;
  css += `.port[data-palette="${p.id}"][data-theme="dark"] {\n${decls(p.dark)}\n}\n`;
  if (p.id === "contrast") {
    css += `@media (prefers-contrast: more) {\n  .port:not([data-palette]), .port[data-palette="stone"] {\n${decls(p.light).replace(/^/gm, "  ")}\n  }\n  .port[data-theme="dark"]:not([data-palette]), .port[data-theme="dark"][data-palette="stone"] {\n${decls(p.dark).replace(/^/gm, "  ")}\n  }\n}\n`;
    css += `.port[data-palette="contrast"] { --shadow-tile: none; --shadow-well: none; }
.port[data-palette="contrast"] :is(.panel, .tile, .menu, .dlg, .setcard, .pop, .cal, .cmdk) { box-shadow: 0 0 0 1px var(--line-strong); }
.port[data-palette="contrast"] .row.is-selected { box-shadow: inset 0 0 0 2px var(--hue); }
.port[data-palette="contrast"] .btn { border-color: var(--line-strong); }
.port[data-palette="contrast"] :focus-visible { outline-width: 3px !important; }
`;
  }
  presetCss[p.id] = css;
  write(out(`themes/${p.id}.css`), css);
}

/* ---------- components ---------- */
const cssFiles = fs.readdirSync(src("css")).filter((f) => f.endsWith(".css")).sort();
const components = banner + cssFiles.map((f) => read(src("css/" + f))).join("\n");
write(out("components.css"), components);
const fonts = banner + `/* Port's type: IBM Plex Sans + IBM Plex Mono (SIL Open Font License).
   This file loads them from Google Fonts. For offline/desktop apps, self-host instead:
   npm i @fontsource/ibm-plex-sans @fontsource/ibm-plex-mono and import their CSS. */
@import url("https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600&family=IBM+Plex+Sans:wght@400;500;600;700&display=swap");
`;
write(out("fonts.css"), fonts);
write(out("port.css"), banner + `/* All-in-one: tokens + every preset + components. Fonts are separate (fonts.css). */\n` +
  tokensCss.replace(banner, "") + Object.values(presetCss).map((c) => c.replace(banner, "")).join("\n") + components.replace(banner, ""));

/* ---------- JS ---------- */
const core = read(src("js/core.js"));
write(out("port.mjs"), banner + `const Port = (function () {\n"use strict";\n` + core + `\nreturn api;\n})();\nexport default Port;\nexport const { init, configure, wire, icon, keys, applyKeys, detectPlatform, sglyph, open, close, toast, sortTable, sliderSet, feedback, windowControls, version } = Port;\n`);
write(out("port.umd.js"), banner + `(function (g, f) { if (typeof module === "object" && module.exports) module.exports = f(); else if (typeof define === "function" && define.amd) define([], f); else g.Port = f(); })(typeof self !== "undefined" ? self : this, function () {\n"use strict";\n` + core + `\nreturn api;\n});\n`);
write(out("port.d.ts"), read(src("js/port.d.ts")));
write(out("port.d.mts"), read(src("js/port.d.ts")));

/* ---------- tokens as data ---------- */
write(out("tokens.json"), JSON.stringify(T, null, 2));
write(out("presets.json"), JSON.stringify(PRE, null, 2));
const dtcg = { $description: "Port tokens in W3C Design Tokens (DTCG) format. Colours carry light and dark in $extensions." , color: {}, spacing: {}, radius: {}, font: {}, motion: {}, shadow: {} };
for (const t of T.color.tokens) dtcg.color[t.name] = { $type: "color", $value: val(t.value, "light"), $description: t.usage, $extensions: { "port.modes": { light: val(t.value, "light"), dark: val(t.value, "dark") } } };
for (const t of T.spacing.tokens) dtcg.spacing[t.name] = { $type: "dimension", $value: t.value, $description: t.usage };
for (const t of T.radius.tokens) dtcg.radius[t.name] = { $type: "dimension", $value: t.value, $description: t.usage };
for (const [k, v] of Object.entries(T.type.families)) dtcg.font[k] = { $type: "fontFamily", $value: v };
for (const t of T.motion?.tokens || []) dtcg.motion[t.name] = { $type: t.name.startsWith("d") ? "duration" : "cubicBezier", $value: t.value, $description: t.usage };
for (const t of T.shadow?.tokens || []) dtcg.shadow[t.name] = { $type: "shadow", $value: val(t.value, "light"), $extensions: { "port.modes": { light: val(t.value, "light"), dark: val(t.value, "dark") } } };
write(out("tokens.dtcg.json"), JSON.stringify(dtcg, null, 2));
const tokensJs = { color: Object.fromEntries(T.color.tokens.map((t) => [t.name, { light: val(t.value, "light"), dark: val(t.value, "dark") }])), ...Object.fromEntries(Object.entries(staticVars).map(([k, v]) => [k, v])) };
write(out("tokens.mjs"), banner + `export const tokens = ${JSON.stringify(tokensJs, null, 2)};\nexport const presets = ${JSON.stringify(PRE.presets.map((p) => ({ id: p.id, name: p.name, description: p.description })), null, 2)};\nexport default tokens;\n`);

/* ---------- Tailwind preset (v3 & v4-compatible via CSS variables) ---------- */
const twColors = Object.fromEntries(T.color.tokens.map((t) => [t.name, `var(--${t.name})`]));
write(out("tailwind-preset.cjs"), banner + `// Use inside a .port root so the variables resolve.  tailwind.config.js: presets: [require("@port/ui/tailwind")]\nmodule.exports = {\n  theme: { extend: {\n    colors: { port: ${JSON.stringify(twColors, null, 6)} },\n    borderRadius: ${JSON.stringify(Object.fromEntries(T.radius.tokens.map((t) => ["port-" + t.name.replace("radius-", ""), `var(--${t.name})`])), null, 6)},\n    spacing: ${JSON.stringify(Object.fromEntries(T.spacing.tokens.map((t) => ["port-" + t.name.replace("space-", ""), `var(--${t.name})`])), null, 6)},\n    fontFamily: { "port-sans": "var(--font-sans)", "port-mono": "var(--font-mono)", "port-display": "var(--font-display)" },\n    boxShadow: ${JSON.stringify(Object.fromEntries((T.shadow?.tokens || []).map((t) => ["port-" + t.name.replace("shadow-", ""), `var(--${t.name})`])), null, 6)},\n    transitionTimingFunction: { "port-out": "var(--motion-e-out)", "port-spring": "var(--motion-e-spring)" },\n    transitionDuration: { "port-1": "var(--motion-d1)", "port-2": "var(--motion-d2)", "port-3": "var(--motion-d3)", "port-4": "var(--motion-d4)" }\n  } }\n};\n`);

/* ---------- icons ---------- */
const icons = fs.readdirSync(src("icons")).filter((f) => f.endsWith(".svg")).sort();
let sprite = `<svg xmlns="http://www.w3.org/2000/svg" style="display:none">\n`;
const iconMap = {};
for (const f of icons) {
  const svg = read(src("icons/" + f)); const name = f.replace(".svg", "");
  write(out("icons/" + f), svg);
  const d = svg.match(/ d="([^"]+)"/)[1]; iconMap[name] = d;
  sprite += `  <symbol id="port-${name}" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="${d}"/></symbol>\n`;
}
write(out("icons/sprite.svg"), sprite + "</svg>\n");
write(out("icons.d.mts"), `export declare const iconPaths: Record<string, string>;\nexport declare const iconNames: string[];\ndeclare const _default: Record<string, string>;\nexport default _default;\n`);
write(out("tokens.d.mts"), `export declare const tokens: { color: Record<string, { light: string; dark: string }>; [k: string]: unknown };\nexport declare const presets: Array<{ id: string; name: string; description: string }>;\nexport default tokens;\n`);
write(out("icons.mjs"), banner + `export const iconPaths = ${JSON.stringify(iconMap, null, 2)};\nexport const iconNames = Object.keys(iconPaths);\nexport default iconPaths;\n`);

const files = [];
(function walk(d) { for (const f of fs.readdirSync(d)) { const p = path.join(d, f); fs.statSync(p).isDirectory() ? walk(p) : files.push(path.relative(root, p)); } })(out(""));
console.log(`@port/ui ${pkg.version}: built ${files.length} files into dist/`);
